import Foundation
import Testing
@testable import WultraMobileTokenSDK

struct ProvisioningUtilsTests {
    
    // provisioning profile parsing
    
    @Test
    func testParseProvisioningProfile() {
        guard let data = Data(base64Encoded: base64ProductionProfile) else {
            Issue.record("Could not decode base64 profile")
            return
        }
        let profile = WMTProvisioningUtils.getProvisioningProfileFromData(data)
        #expect(profile?.entitlements.apsEnvironment == .production)
    }
    
    // plist parsing
    
    @Test
    func testParseDevelopmentAPNS() {
        let plist = getPlist("development")
        let profile = WMTProvisioningUtils.parseProvisioningProfilePlist(plist)
        #expect(profile?.entitlements.apsEnvironment == .development)
    }
    
    @Test
    func testParseProductionAPNS() {
        let plist = getPlist("production")
        let profile = WMTProvisioningUtils.parseProvisioningProfilePlist(plist)
        #expect(profile?.entitlements.apsEnvironment == .production)
    }
    
    @Test
    func testParseMissingAPNS() {
        let plist = getPlist(nil)
        let profile = WMTProvisioningUtils.parseProvisioningProfilePlist(plist)
        #expect(profile?.entitlements.apsEnvironment == nil)
    }
    
    @Test
    func testParseUnknownAPNS() {
        let plist = getPlist("integration") // unknown value
        let profile = WMTProvisioningUtils.parseProvisioningProfilePlist(plist)
        #expect(profile?.entitlements.apsEnvironment == nil)
    }
    
    private func getPlist(_ apnsEnvironment: String?) -> Data {
        let entry = if let apnsEnvironment {
            "<key>aps-environment</key><string>\(apnsEnvironment)</string>"
        } else {
            ""
        }
        return "<plist version=\"1.0\"> <dict> <key>AppIDName</key> <string>for testing purposes</string> <key>ApplicationIdentifierPrefix</key> <array> <string>ASDASDASD</string> </array> <key>CreationDate</key> <date>2024-01-08T10:59:17Z</date> <key>Platform</key> <array> <string>iOS</string> <string>xrOS</string> <string>visionOS</string> </array> <key>IsXcodeManaged</key> <true/> <key>DeveloperCertificates</key> <array> <data>pqi3u4hrjkanfkjanldfjkansd;;f</data> </array> <key>DER-Encoded-Profile</key> <data></data> <key>Entitlements</key> <dict> \(entry) <key>com.apple.security.application-groups</key> <array> <string>group.com.wultra.testGroup</string> </array> <key>application-identifier</key> <string>ASDASDASD.com.wultra.test</string> <key>keychain-access-groups</key> <array> <string>ASDASDASD.*</string> <string>com.apple.token</string> </array> <key>get-task-allow</key> <true/> <key>com.apple.developer.team-identifier</key> <string>ASDASDASD</string> </dict> <key>ExpirationDate</key> <date>2025-01-07T10:59:17Z</date> <key>Name</key> <string>iOS Team Provisioning Profile: com.wultra.test</string> <key>ProvisionedDevices</key> <array> <string>00008101-000528D93A12001E</string> <string>00008101-001C34EC2250801E</string> <string>00008030-000975CC0AEA802E</string> <string>00008101-001269DE0A50001E</string> </array> <key>TeamIdentifier</key> <array> <string>ASDASDASD</string> </array> <key>TeamName</key> <string>Wultra</string> <key>TimeToLive</key> <integer>365</integer> <key>UUID</key> <string>7749747f-897e-45f3-b78e-d327a1c9f38a</string> <key>Version</key> <integer>1</integer> </dict> </plist>".data(using: .utf8)!
    }
    
    // real base64 encoded embedded.mobileprovisioning from the testflight app with a profuction apns
    private let base64ProductionProfile = ""
}
